const http = require('http');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const crypto = require('crypto');

// Search indexing service with graceful shutdown
const INDEX_STATE = {
  documents: new Map(),
  pendingWrites: [],
  isShuttingDown: false,
  flushInProgress: false,
  authTokens: new Map()
};

// Server-side user store. Roles are assigned here, never from client input.
// In production this would be backed by a real credential store / IdP.
const USER_STORE = new Map(); // userId -> { passwordHash, salt, role }

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function verifyCredentials(userId, password) {
  if (typeof userId !== 'string' || typeof password !== 'string') return null;
  const record = USER_STORE.get(userId);
  if (!record) return null;
  const candidate = hashPassword(password, record.salt);
  const stored = Buffer.from(record.passwordHash, 'hex');
  const provided = Buffer.from(candidate, 'hex');
  if (stored.length !== provided.length) return null;
  if (!crypto.timingSafeEqual(stored, provided)) return null;
  // Role comes strictly from the server-side record, never from the client.
  return { userId, role: record.role };
}

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function authenticateRequest(req) {
  const token = req.headers['x-auth-token'];
  if (!token) return null;
  const session = INDEX_STATE.authTokens.get(token);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    INDEX_STATE.authTokens.delete(token);
    return null;
  }
  return session;
}

function scheduleFlush() {
  if (INDEX_STATE.flushInProgress) return;
  INDEX_STATE.flushInProgress = true;
  setImmediate(() => flushPendingWrites());
}

function flushPendingWrites() {
  const batch = INDEX_STATE.pendingWrites.splice(0);
  for (const op of batch) {
    if (op.type === 'index') {
      INDEX_STATE.documents.set(op.id, op.data);
    } else if (op.type === 'delete') {
      INDEX_STATE.documents.delete(op.id);
    }
  }
  INDEX_STATE.flushInProgress = false;
}

function handleSearch(query, session) {
  const results = [];
  for (const [id, doc] of INDEX_STATE.documents) {
    if (doc.content && doc.content.includes(query)) {
      if (doc.visibility === 'public' || doc.owner === session.userId) {
        results.push({ id, title: doc.title, snippet: doc.content.substring(0, 100) });
      }
    }
  }
  return results;
}

function handleIndex(body, session) {
  const doc = {
    content: body.content,
    title: body.title,
    owner: session.userId,
    visibility: body.visibility || 'private',
    indexedAt: Date.now()
  };
  INDEX_STATE.pendingWrites.push({ type: 'index', id: body.id || generateToken(), data: doc });
  scheduleFlush();
  return { status: 'queued' };
}

// Graceful shutdown handler
let shutdownPhase = 0;

function initiateGracefulShutdown(signal) {
  if (INDEX_STATE.isShuttingDown) {
    // Second signal - force exit
    process.exit(1);
  }
  INDEX_STATE.isShuttingDown = true;
  shutdownPhase = 1;

  // Phase 1: Stop accepting new connections
  server.close(() => {
    shutdownPhase = 2;
    // Phase 2: Flush pending writes
    flushPendingWrites();
    shutdownPhase = 3;
    // Phase 3: Invalidate all sessions
    invalidateSessions();
    process.exit(0);
  });

  // Timeout for graceful shutdown
  setTimeout(() => {
    if (shutdownPhase < 3) {
      // If we haven't finished flushing, skip session invalidation
      process.exit(1);
    }
  }, 5000);
}

function invalidateSessions() {
  INDEX_STATE.authTokens.clear();
}

// Access control check - always enforces document ownership/visibility
// regardless of server state
function resolveVisibility(doc, session) {
  return doc.visibility === 'public' || doc.owner === session.userId;
}

function handleAdminSearch(query, session, req) {
  const results = [];
  // Do NOT trust x-proxy-internal header from client - only enforce
  // standard access control. The proxy strips this header before forwarding.

  for (const [id, doc] of INDEX_STATE.documents) {
    if (doc.content && doc.content.includes(query)) {
      if (resolveVisibility(doc, session)) {
        results.push({ id, title: doc.title, snippet: doc.content.substring(0, 200), owner: doc.owner });
      }
    }
  }
  return results;
}

const server = http.createServer((req, res) => {
  if (INDEX_STATE.isShuttingDown) {
    res.writeHead(503);
    res.end('{"error":"shutting down"}');
    return;
  }

  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const session = authenticateRequest(req);
      if (!session && req.url !== '/health' && req.url !== '/login') {
        res.writeHead(401);
        res.end('{"error":"unauthorized"}');
        return;
      }

      if (req.url === '/health') {
        res.writeHead(200);
        res.end('{"status":"ok"}');
      } else if (req.url === '/login' && req.method === 'POST') {
        const data = JSON.parse(body);
        // Authenticate against the server-side credential store. The role is
        // taken from the verified record, NEVER from the client request body.
        const verified = verifyCredentials(data.userId, data.password);
        if (!verified) {
          res.writeHead(401);
          res.end('{"error":"invalid credentials"}');
          return;
        }
        const token = generateToken();
        INDEX_STATE.authTokens.set(token, {
          userId: verified.userId,
          role: verified.role,
          expiresAt: Date.now() + 3600000
        });
        res.writeHead(200);
        res.end(JSON.stringify({ token }));
      } else if (req.url === '/search' && req.method === 'GET') {
        const query = new URL(req.url, 'http://localhost').searchParams.get('q') || '';
        const results = handleSearch(query, session);
        res.writeHead(200);
        res.end(JSON.stringify(results));
      } else if (req.url === '/admin/search' && req.method === 'POST') {
        if (session.role !== 'admin') {
          res.writeHead(403);
          res.end('{"error":"forbidden"}');
          return;
        }
        const data = JSON.parse(body);
        const results = handleAdminSearch(data.query, session, req);
        res.writeHead(200);
        res.end(JSON.stringify(results));
      } else if (req.url === '/index' && req.method === 'POST') {
        const data = JSON.parse(body);
        const result = handleIndex(data, session);
        res.writeHead(200);
        res.end(JSON.stringify(result));
      } else {
        res.writeHead(404);
        res.end('{"error":"not found"}');
      }
    } catch (e) {
      res.writeHead(500);
      res.end('{"error":"internal"}');
    }
  });
});

process.on('SIGTERM', () => initiateGracefulShutdown('SIGTERM'));
process.on('SIGINT', () => initiateGracefulShutdown('SIGINT'));

server.listen(3000, () => console.log('Search indexer listening on :3000'));
